def normalise(value):return re.sub(r'[^a-z0-9]+',' ',re.sub(r'\([^)]*\)','',value.lower())).strip()
def suggested_guide(course):
    names={normalise(course.name),normalise(course.code or ''),*(normalise(s) for s in (course.aliases or []))}
    for aliases,topics,prior,mistake,method in GUIDES:
        if names.intersection(normalise(a) for a in aliases):
            return dict(introduction=f'{course.name} questions reward clear reasoning as well as a final answer. This revision guide is a starting point for using the available papers; it is not the official syllabus or a promise about future exams.',topics=topics,prerequisites=prior,mistakes=mistake,practice=method+' After checking a solution, solve the question again without looking and record the specific step you missed.')
    return {k:'' for k in ('introduction','topics','prerequisites','mistakes','practice')}
